/**
 * @name Charset-normalizer CLI command injection via os/system/subprocess
 * @description Find uses of dangerous command execution APIs that may be influenced by CLI/user input.
 * @kind path-problem
 * @problem.severity error
 * @id py/charset-normalizer/cli-command-injection
 * @tags security
 *       external/cwe/cwe-078
 */

import python
import semmle.python.ApiGraphs
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.dataflow.new.RemoteFlowSources

module CliCmdInjConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    source instanceof RemoteFlowSource
  }

  predicate isSink(DataFlow::Node sink) {
    exists(API::CallNode call |
      sink = call and
      (
        call = API::moduleImport("os").getMember(["system", "popen"]).getACall() or
        call = API::moduleImport("subprocess").getMember(["Popen", "call", "check_call", "check_output", "run"]).getACall()
      )
    )
  }
}

module CliCmdInjFlow = TaintTracking::Global<CliCmdInjConfig>;
import CliCmdInjFlow::PathGraph

from CliCmdInjFlow::PathNode source, CliCmdInjFlow::PathNode sink
where CliCmdInjFlow::flowPath(source, sink)
select sink.getNode(), source, sink, "User-controlled data reaches command execution $@.", source.getNode(), "user input"

/**
 * @name Charset-normalizer unsafe file write from untrusted input
 * @description Track flow from remote/CLI input to file write operations that could overwrite arbitrary files.
 * @kind path-problem
 * @problem.severity error
 * @id py/charset-normalizer/unsafe-file-write
 * @tags security
 *       external/cwe/cwe-073
 */

import python
import semmle.python.ApiGraphs
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.dataflow.new.RemoteFlowSources

module FileWriteConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    source instanceof RemoteFlowSource
  }

  predicate isSink(DataFlow::Node sink) {
    exists(API::CallNode call |
      sink = call and
      (
        // built-in open
        call = API::builtin("open").getACall() or
        // os.open
        call = API::moduleImport("os").getMember("open").getACall() or
        // shutil.file operations
        call = API::moduleImport("shutil").getMember(["copy", "copy2", "copyfile", "move"]).getACall()
      )
    )
  }
}

module FileWriteFlow = TaintTracking::Global<FileWriteConfig>;
import FileWriteFlow::PathGraph

from FileWriteFlow::PathNode source, FileWriteFlow::PathNode sink
where FileWriteFlow::flowPath(source, sink)
select sink.getNode(), source, sink, "User-controlled data reaches file write or path-manipulating API $@.", source.getNode(), "user input"
